const factions={Unaffiliated:'No banner. No promises. Every door stays open.',Pickers:'Scavengers who know every useful thing in a heap.',Hawkers:'Deal-makers. They trade in needs, never tokens.',Reapers:'The strong take what the weak cannot keep.',Delvers:'A sacred search for the way out. You do not leave.',Wardens:'Protection for hire. Their loyalties have a price.'};
const origins={Drifter:'Quick hands, little trust.',Foundling:'Toughened by the lower runs.',Exile:'A hard lesson in being watched.'};
let s={name:'Marlow',origin:'Drifter',tone:0,build:0,scar:0,day:1,turn:0,loc:'The Heap',faction:'Unaffiliated',hp:82,hunger:77,thirst:72,stamina:82,inventory:{'Bent pipe':1,'Ration':1,'Scrap':2,'Cloth':1,'Dirty water':1},wounds:[],shelter:0,flags:{},logs:[],enemy:null,dead:false};
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));const rand=(a,b)=>Math.floor(Math.random()*(b-a+1));
function log(text,tag=''){s.logs.unshift({text,tag});s.logs=s.logs.slice(0,7)}
function notify(text){const n=document.createElement('div');n.className='toast';n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),2400)}
function inventoryCount(item){return s.inventory[item]||0}function add(item,n=1){s.inventory[item]=(s.inventory[item]||0)+n;}
let renderer,scene,camera,model,modelParts={};
function makeClothTexture(){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle='#81715a';x.fillRect(0,0,256,256);for(let i=0;i<4200;i++){x.fillStyle=Math.random()>.5?'#302e27':'#c3a887';x.globalAlpha=Math.random()*.22;x.fillRect(Math.random()*256,Math.random()*256,1+Math.random()*4,1+Math.random()*4)}x.globalAlpha=1;return new THREE.CanvasTexture(c)}
function addLimb(parent,name,geom,mat,pos){const mesh=new THREE.Mesh(geom,mat);mesh.position.set(...pos);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);modelParts[name]=mesh;return mesh}
function buildModel(){if(!scene)return;if(model)scene.remove(model);model=new THREE.Group();scene.add(model);const colors=['#936c54','#bd8b69','#664b3b','#d0a07b'];const skinMat=new THREE.MeshStandardMaterial({color:colors[s.tone],roughness:1});const clothMat=new THREE.MeshStandardMaterial({map:makeClothTexture(),color:s.build===0?'#77745e':s.build===1?'#655748':'#74665a',roughness:1});const dark=new THREE.MeshStandardMaterial({color:'#37352c',roughness:1});const boot=new THREE.MeshStandardMaterial({color:'#39352c',roughness:.95});
// torso and battered layered clothes
addLimb(model,'torso',new THREE.CapsuleGeometry(.38,.72,7,10),clothMat,[0,1.08,0]);addLimb(model,'shirt',new THREE.CapsuleGeometry(.32,.43,5,8),new THREE.MeshStandardMaterial({color:'#8a795f',roughness:1}),[0,1.4,.015]);
addLimb(model,'head',new THREE.SphereGeometry(.24,16,12),skinMat,[0,2.01,0]);modelParts.head.scale.set(.86,1.12,.88);
addLimb(model,'hair',new THREE.SphereGeometry(.245,14,9,0,Math.PI*2,0,Math.PI*.52),dark,[0,2.11,-.016]);
addLimb(model,'nose',new THREE.ConeGeometry(.045,.12,6),skinMat,[0,1.99,.23]);
for(const side of [-1,1]){addLimb(model,'arm'+side,new THREE.CapsuleGeometry(.105,.57,5,7),clothMat,[side*.47,1.22,0]).rotation.z=-side*.18;addLimb(model,'hand'+side,new THREE.SphereGeometry(.1,10,8),skinMat,[side*.49,.81,.025]);addLimb(model,'leg'+side,new THREE.CapsuleGeometry(.14,.56,5,8),dark,[side*.19,.39,0]);addLimb(model,'boot'+side,new THREE.BoxGeometry(.23,.13,.38),boot,[side*.19,.09,.07]);}
// rough protective shoulder patch and scavenged belt
const belt=addLimb(model,'belt',new THREE.TorusGeometry(.27,.055,6,16),dark,[0,.82,0]);belt.rotation.x=Math.PI/2;
addLimb(model,'shoulder',new THREE.BoxGeometry(.25,.16,.3),new THREE.MeshStandardMaterial({color:'#514b3c',roughness:1}),[-.35,1.56,0]).rotation.z=.15;
// grime streaks over skin and garment, uneven russet stains
const grime=new THREE.MeshStandardMaterial({color:'#39332a',roughness:1});for(let i=0;i<8;i++){const mark=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.06,7,6),grime);mark.scale.set(1,.26,.35);mark.position.set((Math.random()-.5)*.52,.83+Math.random()*1.05,.25);model.add(mark)}
// visible scar, toggled by slider
const scarMat=new THREE.MeshStandardMaterial({color:'#a87963',roughness:1});if(s.scar>20){const scar=new THREE.Mesh(new THREE.BoxGeometry(.014,.15,.014),scarMat);scar.position.set(.085,2.025,.205);scar.rotation.z=-.42;model.add(scar)}
model.position.y=-.05;}
function initModel(){const el=document.querySelector('#model-canvas');if(!el)return;renderer=new THREE.WebGLRenderer({canvas:el,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(el.clientWidth,el.clientHeight,false);renderer.setClearColor(0,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,el.clientWidth/el.clientHeight,.1,100);camera.position.set(0,1.5,5.6);camera.lookAt(0,1.13,0);scene.add(new THREE.HemisphereLight('#d8d0b3','#35352b',2.1));let key=new THREE.DirectionalLight('#f0d7b4',3.3);key.position.set(-3,4,4);scene.add(key);let rim=new THREE.DirectionalLight('#9bac8d',2);rim.position.set(3,2,-3);scene.add(rim);const floor=new THREE.Mesh(new THREE.CircleGeometry(2,32),new THREE.MeshStandardMaterial({color:'#454438',roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.035;scene.add(floor);buildModel();let pointer=0;el.onpointermove=e=>{const r=el.getBoundingClientRect();pointer=((e.clientX-r.left)/r.width-.5)*.4};function animate(){if(!renderer||!document.querySelector('#model-canvas'))return;model.rotation.y+=(pointer-model.rotation.y)*.035+0.0015;renderer.render(scene,camera);requestAnimationFrame(animate)}animate();new ResizeObserver(()=>{if(!renderer||!el.isConnected)return;renderer.setSize(el.clientWidth,el.clientHeight,false);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix()}).observe(el)}
function creator(){app.innerHTML=`<section id="creator"><div class="topline"><div class="brand">THE CRAG <b> / FIELD RECORD 001</b></div><div class="eyebrow">A survival story · Beneath the Utopia</div></div><div class="creator-grid"><div class="create-copy"><div class="eyebrow">Character file · New arrival</div><h1 class="title">Beneath<br>the <span>Utopia.</span></h1><p class="intro">Upstairs, they call it perfect. Down here, the things they throw away keep you alive. Nobody comes back from speaking out. You have just fallen through the cracks.</p><div class="section-label">Name</div><input id="name-input" class="field" maxlength="18" value="${s.name}" placeholder="What do they call you?" aria-label="Character name"><div class="section-label">What brought you here?</div><div class="origin-grid">${Object.entries(origins).map(([k,v])=>`<button class="origin ${s.origin===k?'active':''}" data-origin="${k}"><strong>${k}</strong><small>${v}</small></button>`).join('')}</div><div class="section-label">Make yourself</div><div class="appearance"><div class="slider-row"><label>Complexion <span id="tone-value">${['Ash-brown','Warm umber','Deep earth','Sunless clay'][s.tone]}</span></label><input id="tone" type="range" min="0" max="3" value="${s.tone}"></div><div class="slider-row"><label>Build <span id="build-value">${['Lean','Sturdy','Wiry'][s.build]}</span></label><input id="build" type="range" min="0" max="2" value="${s.build}"></div><div class="slider-row"><label>Old scars <span id="scar-value">${s.scar}%</span></label><input id="scar" type="range" min="0" max="100" value="${s.scar}"></div><div class="slider-row"><label>Model <span>drag to turn</span></label><div class="creator-note">A body shaped by the long fall. Clothes from somebody else's discarded life.</div></div></div><div class="create-foot"><button id="begin" class="btn primary">Enter the Crag →</button><span class="creator-note">No daylight. No currency. No easy way back.</span></div></div><div class="model-wrap"><canvas id="model-canvas" aria-label="Rotating 3D character model"></canvas><div class="model-mark"></div><div class="model-overlay model-top eyebrow">Three-dimensional likeness · scavenged kit</div><div class="model-help">DRAG TO ROTATE</div><div class="model-overlay model-caption"><div><strong id="model-name">${s.name}</strong><br><small>NO SUN · DAY 01</small></div><div class="eyebrow">FIG. 01 — SUBJECT</div></div></div></div></section>`;
initModel();document.querySelectorAll('[data-origin]').forEach(b=>b.onclick=()=>{s.origin=b.dataset.origin;document.querySelectorAll('[data-origin]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('#name-input').oninput=e=>{s.name=e.target.value||'Nobody';document.querySelector('#model-name').textContent=s.name};document.querySelector('#tone').oninput=e=>{s.tone=+e.target.value;document.querySelector('#tone-value').textContent=['Ash-brown','Warm umber','Deep earth','Sunless clay'][s.tone];buildModel()};document.querySelector('#build').oninput=e=>{s.build=+e.target.value;document.querySelector('#build-value').textContent=['Lean','Sturdy','Wiry'][s.build];if(model)model.scale.x=[.9,1.15,.88][s.build];buildModel()};document.querySelector('#scar').oninput=e=>{s.scar=+e.target.value;document.querySelector('#scar-value').textContent=s.scar+'%';buildModel()};document.querySelector('#begin').onclick=()=>{s.name=s.name.trim()||'Nobody';if(s.origin==='Foundling'){s.hp=94;s.inventory.Ration=2}else if(s.origin==='Exile'){s.stamina=94;s.inventory.Scrap=3}log(`${s.name} drops into the Heap with one bent pipe and a bad feeling.`,'start');game()}}

let worldRenderer,worldScene,worldCamera,worldAnimation=0;
const places={"The Heap":{desc:'A mountain of yesterday’s luxuries.',coords:'LOWER SINK · 04 / 19',threat:'Scavenger trails · low threat',color:'#47463a'},"Dripmarket":{desc:'A market stitched into the condensation pipes.',coords:'MID-CRAG · 12 / 06',threat:'Eyes everywhere · watch your pockets',color:'#4d4937'},"Red Gut":{desc:'A rust-red crawlspace. Something lives in the dark.',coords:'LOWER GUT · 02 / 31',threat:'Movement in the rubble · high threat',color:'#543c32'},"Old Lift":{desc:'The elevator shaft goes up farther than sight.',coords:'NORTH SHAFT · 00 / 01',threat:'Delver marks · unknown danger',color:'#3c4945'}};
function makeWorld(){const canvas=document.querySelector('#scene-canvas');if(!canvas)return;worldRenderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});worldRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));worldRenderer.setSize(canvas.clientWidth,canvas.clientHeight,false);worldRenderer.outputColorSpace=THREE.SRGBColorSpace;worldRenderer.toneMapping=THREE.ACESFilmicToneMapping;worldScene=new THREE.Scene();worldScene.background=new THREE.Color('#22231f');worldScene.fog=new THREE.FogExp2('#22231f',.035);worldCamera=new THREE.PerspectiveCamera(49,canvas.clientWidth/canvas.clientHeight,.1,90);worldCamera.position.set(0,3.8,11);worldCamera.lookAt(0,1.5,-3);worldScene.add(new THREE.HemisphereLight('#a9a58b','#171914',1.45));const lamp=new THREE.PointLight('#e7c585',42,17,1.7);lamp.position.set(-2,5,-2);worldScene.add(lamp);const cold=new THREE.PointLight('#7d9a8b',15,15);cold.position.set(5,2,-7);worldScene.add(cold);
const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness});const stone=[mat('#34352f'),mat('#49483c'),mat('#555143'),mat('#262822')],rust=mat('#664d3c'),metal=mat('#6a6654',.82);const floor=new THREE.Mesh(new THREE.PlaneGeometry(90,90),mat('#292a24'));floor.rotation.x=-Math.PI/2;floor.position.y=-.12;worldScene.add(floor);
// overhead vault and broken, irregular rock teeth
const roof=new THREE.Mesh(new THREE.BoxGeometry(70,.65,65),stone[3]);roof.position.set(0,8,-8);worldScene.add(roof);
for(let i=0;i<38;i++){const side=i%2===0?-1:1,z=-20+Math.random()*31;const h=2+Math.random()*5;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.7+Math.random()*1.7,1),stone[rand(0,3)]);rock.scale.set(.7+Math.random(),h/(1.2+Math.random()),.8+Math.random());rock.position.set(side*(5+Math.random()*10),h/2-0.1,z);rock.rotation.set(Math.random(),Math.random(),Math.random()*.25);rock.castShadow=true;worldScene.add(rock)}
// looming buttresses framing the passage
for(const x of [-7,-4.8,4.8,7]){const pillar=new THREE.Mesh(new THREE.CylinderGeometry(.42,.85,7,5),stone[rand(0,2)]);pillar.position.set(x,3.2,-4-(Math.abs(x)>6?3:0));pillar.rotation.z=(Math.random()-.5)*.11;worldScene.add(pillar)}
// discarded domestic objects - a velvet couch, cracked lamp, and e-waste
const couch=new THREE.Group();const seat=new THREE.Mesh(new THREE.BoxGeometry(2.4,.42,1),mat('#69543e'));seat.position.y=.56;couch.add(seat);const back=new THREE.Mesh(new THREE.BoxGeometry(2.4,.9,.3),mat('#78604a'));back.position.set(0,1.05,-.36);couch.add(back);for(const x of [-1,1]){const arm=new THREE.Mesh(new THREE.BoxGeometry(.32,.68,.95),mat('#65503d'));arm.position.set(x*1.05,.72,0);couch.add(arm);const leg=new THREE.Mesh(new THREE.BoxGeometry(.13,.5,.13),metal);leg.position.set(x*.85,.2,.3);couch.add(leg)}couch.position.set(-3,.03,-2);couch.rotation.y=.27;worldScene.add(couch);
const heap=new THREE.Group();for(let i=0;i<25;i++){const g=i%3===0?new THREE.BoxGeometry(.3+Math.random()*.8,.15+Math.random()*.45,.2+Math.random()*.7):new THREE.DodecahedronGeometry(.2+Math.random()*.45,0);const o=new THREE.Mesh(g,i%4===0?rust:stone[rand(0,3)]);o.position.set((Math.random()-.5)*4,Math.random()*.35,(Math.random()-.5)*2);o.rotation.set(Math.random(),Math.random(),Math.random());heap.add(o)}heap.position.set(3,0,-1);worldScene.add(heap);
// pipework above, with dripping leak and a distant opening
for(let i=0;i<5;i++){const pipe=new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,12,8),metal);pipe.rotation.z=Math.PI/2;pipe.position.set(0,6.6-i*.42,-8-i*2.7);worldScene.add(pipe)}const arch=new THREE.Mesh(new THREE.TorusGeometry(2.9,.2,8,24,Math.PI),metal);arch.position.set(0,3.8,-18);arch.rotation.y=Math.PI/2;worldScene.add(arch);
// tiny amber work lights
for(const p of [[-5,3,-7],[4,2,-13],[1,5,-22]]){const bulb=new THREE.Mesh(new THREE.SphereGeometry(.11,8,6),new THREE.MeshBasicMaterial({color:'#e4b979'}));bulb.position.set(...p);worldScene.add(bulb);const l=new THREE.PointLight('#d99e61',5,9);l.position.set(...p);worldScene.add(l)}
let t=0;function frame(){if(!canvas.isConnected)return;t+=.008;worldCamera.position.x=Math.sin(t)*.18;worldCamera.position.y=3.8+Math.sin(t*.7)*.06;worldCamera.lookAt(0,1.5,-3);worldRenderer.render(worldScene,worldCamera);worldAnimation=requestAnimationFrame(frame)}frame();new ResizeObserver(()=>{if(!canvas.isConnected)return;worldRenderer.setSize(canvas.clientWidth,canvas.clientHeight,false);worldCamera.aspect=canvas.clientWidth/canvas.clientHeight;worldCamera.updateProjectionMatrix()}).observe(canvas)}
function game(){app.innerHTML=`<section id="game"><header class="game-header"><div class="game-title">BENEATH <em>THE UTOPIA</em></div><div class="header-right"><span>CRAG FIELD RECORD 001</span><span class="mono">DAY <b id="header-day">01</b></span><button class="btn" id="menu-button">☰</button></div></header><div class="game-grid"><div class="main-column"><div class="scene"><canvas id="scene-canvas" aria-label="Three-dimensional view of the crag"></canvas><div class="scene-head"><div class="eyebrow" id="scene-eyebrow">A PLACE BELOW THE LIGHT</div><h2 id="place-title">${s.loc}</h2><p id="place-desc"></p></div><div class="scene-coords" id="coords"></div><div class="scene-bottom"><span class="threat" id="threat"></span><div class="location-buttons">${Object.keys(places).map(p=>`<button data-place="${p}" class="${s.loc===p?'active':''}">${p}</button>`).join('')}</div></div></div><div class="action-grid"><button class="action" data-action="scavenge"><span class="icon">⌕</span><strong>Scavenge</strong><small>Search the Heap</small></button><button class="action" data-action="water"><span class="icon">◒</span><strong>Find water</strong><small>Follow the drips</small></button><button class="action" data-action="hunt"><span class="icon">⌁</span><strong>Hunt vermin</strong><small>Rat, grub, or both</small></button><button class="action" data-action="hide"><span class="icon">▧</span><strong>Lie low</strong><small>Catch your breath</small></button><button class="action" data-action="shelter"><span class="icon">⌂</span><strong>Build shelter</strong><small>Scrap + cloth</small></button><button class="action" data-action="trade"><span class="icon">⇄</span><strong>Make a deal</strong><small>Goods for goods</small></button><button class="action" data-action="talk"><span class="icon">◉</span><strong>Talk</strong><small>Make an ally</small></button><button class="action" data-action="travel"><span class="icon">↗</span><strong>Move on</strong><small>Travel the crag</small></button></div><div class="event-log"><div class="log-title"><span>Field notes</span><span>THE CRAG KEEPS SCORE</span></div><div id="logs"></div></div></div><aside class="sidebar"><div class="sidepanel"><div class="side-heading"><span>Survivor</span><span id="origin-label">${s.origin}</span></div><div class="portrait-row"><div class="avatar"></div><div><div class="person-name" id="person-name">${s.name}</div><div class="person-origin">LOWER SINK · NO PAPERS</div></div></div><div id="meters"></div><div id="wound" class="wound-row"></div><div class="quick-stats"><div class="stat-chip"><b id="shelter-level">${s.shelter?'I':'—'}</b><small>Shelter</small></div><div class="stat-chip"><b>${s.faction==='Unaffiliated'?'—':s.faction.slice(0,3).toUpperCase()}</b><small>Faction</small></div><div class="stat-chip"><b id="turn-count">${s.turn}</b><small>Actions</small></div></div></div><div class="sidepanel"><div class="side-heading"><span>What you carry</span><span>NO CURRENCY</span></div><div class="inventory-list" id="inventory"></div></div><div class="sidepanel"><div class="side-heading"><span>Faction ties</span><span>● ACTIVE</span></div><div class="faction" id="faction-name">${s.faction}</div><div class="faction-copy" id="faction-copy">${factions[s.faction]}</div></div><div class="sidepanel"><div class="side-heading"><span>Clock</span><span>NO SUN DOWN HERE</span></div><div class="dayline"><span>Crag day</span><strong id="day-count">${String(s.day).padStart(2,'0')}</strong></div><div class="dayline" style="margin-top:7px"><span>At</span><strong id="time-count">${s.turn%4===0?'FIRST WATCH':s.turn%4===1?'SECOND WATCH':s.turn%4===2?'THIRD WATCH':'LAST WATCH'}</strong></div></div></aside></div></section>`;makeWorld();renderStats();renderLogs();document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action));document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>go(b.dataset.place));document.querySelector('#menu-button').onclick=showMenu}
function renderStats(){if(!document.querySelector('#meters'))return;for(const id of ['hp','hunger','thirst','stamina'])s[id]=clamp(s[id]);const effects=s.wounds.reduce((a,w)=>a+w.penalty,0);const stats=[['hp','Health',s.hp,'health'],['hunger','Hunger',s.hunger,'hunger'],['thirst','Thirst',s.thirst,'thirst'],['stamina','Stamina',s.stamina,'stamina']];document.querySelector('#meters').innerHTML=stats.map(([id,n,v,c])=>`<div class="meter"><div class="meter-label"><span>${n}</span><span>${Math.round(v)} / 100</span></div><div class="meter-track"><div class="meter-fill ${c}" style="width:${v}%"></div></div></div>`).join('');const wound=document.querySelector('#wound');if(s.wounds.length){wound.className='wound-row';wound.innerHTML=`⚠ ${s.wounds.map(w=>`${w.name} (−${w.penalty}% ${w.effect})`).join(' · ')}`}else{wound.className='wound-row ok';wound.textContent='✓ No serious injuries'}document.querySelector('#inventory').innerHTML=Object.entries(s.inventory).filter(([,n])=>n>0).map(([item,n])=>`<span class="item-chip">${item} <b>×${n}</b></span>`).join('')||'<span class="item-chip">Empty pockets</span>';document.querySelector('#header-day').textContent=String(s.day).padStart(2,'0');document.querySelector('#day-count').textContent=String(s.day).padStart(2,'0');document.querySelector('#turn-count').textContent=s.turn;document.querySelector('#time-count').textContent=['FIRST WATCH','SECOND WATCH','THIRD WATCH','LAST WATCH'][s.turn%4];document.querySelector('#shelter-level').textContent=s.shelter?'I':'—'}
function renderLogs(){const box=document.querySelector('#logs');if(box)box.innerHTML=s.logs.map(l=>`<div class="logline"><b>${l.tag||'CRAG'}</b> — ${l.text}</div>`).join('')||'<div class="logline">You have not written anything down yet.</div>'}
function updateScene(){document.querySelector('#place-title').textContent=s.loc;document.querySelector('#place-desc').textContent=places[s.loc].desc;document.querySelector('#coords').innerHTML=`${places[s.loc].coords}<br>DEPTH: ${s.loc==='Old Lift'?'UNKNOWN':'2.8 KM'}`;document.querySelector('#threat').textContent=places[s.loc].threat;document.querySelectorAll('[data-place]').forEach(b=>b.classList.toggle('active',b.dataset.place===s.loc))}

function turn(cost=1){s.turn+=cost;if(s.turn%4===0){s.day++;s.hunger-=rand(7,11);s.thirst-=rand(8,13);if(s.shelter)s.hp=Math.min(100,s.hp+5)}s.stamina=clamp(s.stamina);if(s.hunger<=0)s.hp-=7;if(s.thirst<=0)s.hp-=12;if(s.wounds.length)s.hp-=s.wounds.length*2;if(s.hp<=0){s.hp=0;ending('The crag takes what the city threw away.','You ran out of strength in a world that never promised you any. Their perfect city never noticed.');return}renderStats();renderLogs();}
function penalty(){return s.wounds.reduce((a,w)=>a+w.penalty,0)}function actionCost(n=8){return Math.max(2,n+Math.floor(penalty()*.2))}
function actions(key){if(key==='scavenge'){if(s.stamina<actionCost(9)){notify('Too exhausted to search.');return}const picks=s.loc==='The Heap'?['Scrap','Cloth','Ration','Bent pipe','Filter mesh','Wire','Ration']:s.loc==='Dripmarket'?['Filter mesh','Cloth','Scrap','Wire']:s.loc==='Red Gut'?['Rat meat','Scrap','Glass shard','Cloth']:['Wire','Scrap','Battery','Filter mesh'];let found=picks[rand(0,picks.length-1)];add(found,1);s.stamina-=actionCost(9);let text=`You find ${found.toLowerCase()} wedged under something heavier.`;if(Math.random()<.23){s.hp-=rand(3,8);const wound=['Cut hand','Twisted ankle','Ragged gash'][rand(0,2)];s.wounds.push({name:wound,penalty:wound==='Twisted ankle'?20:12,effect:wound==='Twisted ankle'?'travel':'scavenging'});text+=` A sharp edge catches you. ${wound}.`}log(text);turn();return}
if(key==='water'){if(s.loc==='Dripmarket'||Math.random()<.68){add('Dirty water',1);s.thirst=Math.min(100,s.thirst+rand(14,24));s.stamina-=4;log('You collect a mouthful of grey water from a slow pipe. It tastes like pennies.')}else{log('You trace a damp seam to its source. Bone dry.');s.stamina-=3}turn();return}
if(key==='hunt'){if(s.loc!=='Red Gut'&&Math.random()<.44){log('No vermin today. Just the scuttle of something out of sight.');turn();return}const target=Math.random()<.55?'Rat':'Blind beetles';s.enemy={name:target,hp:target==='Rat'?24:19,max:target==='Rat'?24:19,kind:'vermin',damage:rand(7,12)};combat();return}
if(key==='hide'){s.stamina=Math.min(100,s.stamina+22);if(s.shelter){s.hp=Math.min(100,s.hp+9);log('You hunker under your scrap lean-to. Warmth, for once.')}else{log('You squeeze behind the heap and let your pulse slow.')}turn();return}
if(key==='shelter'){if(s.shelter){notify('Your lean-to is already standing.');return}if(inventoryCount('Scrap')<3||inventoryCount('Cloth')<2){notify('Needs 3 scrap and 2 cloth.');return}s.inventory.Scrap-=3;s.inventory.Cloth-=2;s.shelter=1;s.hp=Math.min(100,s.hp+7);log('You lash a lean-to together from bent sheet and rag. It might keep out the drip.');turn();return}
if(key==='trade'){trade();return}if(key==='talk'){talk();return}if(key==='travel'){travel();return}}
function go(place){if(place===s.loc)return;if(s.stamina<actionCost(11)){notify('You need more strength to travel.');return}if(s.loc==='Old Lift'&&place!=='Old Lift'&&s.faction==='Delvers'){notify('Delvers do not turn back.');return}if(s.faction==='Delvers'&&place==='Old Lift'&&s.loc!=='Old Lift'){/* welcomed */}s.loc=place;s.stamina-=actionCost(9);log(`You pick a careful route to ${place}. ${places[place].desc}`);updateScene();turn()}
function modal(title,kicker,content){const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal"><div class="modal-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div><button class="btn close">✕</button></div>${content}</div>`;document.body.append(wrap);wrap.querySelector('.close').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};return wrap}
function trade(){const wrap=modal('Nothing is free.','Hawker at Dripmarket',`<p>“Scrap is a rumour. Bring something I can use, and we can talk about things worth carrying. No coins down here.”</p><div class="choices"><button class="choice" data-trade="blade"><strong>Trade 3 scrap + 1 wire → sharpened shiv</strong><small>Reliable weapon. The price is supposed to hurt.</small></button><button class="choice" data-trade="water"><strong>Trade 1 cloth → clean water ×2</strong><small>Drinkable. Not cheap.</small></button><button class="choice" data-trade="ration"><strong>Trade 2 scrap → sealed ration</strong><small>One more day above the dirt.</small></button><button class="choice" data-trade="deal"><strong>Ask who is recruiting</strong><small>Faction ties change how the crag treats you.</small></button></div>`);wrap.querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>{const t=b.dataset.trade;if(t==='blade'){if(inventoryCount('Scrap')<3||inventoryCount('Wire')<1){notify('The Hawker wants 3 scrap and 1 wire.');return}s.inventory.Scrap-=3;s.inventory.Wire--;add('Sharpened shiv');log('A Hawker parts with a sharpened shiv for three scrap and wire. A fortune in the Crag.')}if(t==='water'){if(!inventoryCount('Cloth')){notify('The Hawker wants one clean piece of cloth.');return}s.inventory.Cloth--;add('Clean water',2);log('You trade cloth for clean water. The Hawker checks every drop.')}if(t==='ration'){if(inventoryCount('Scrap')<2){notify('The Hawker wants 2 scrap.');return}s.inventory.Scrap-=2;add('Ration');log('Two pieces of scrap buy one sealed ration. Weapons cost far more.')}if(t==='deal'){wrap.remove();factionTalk();return}wrap.remove();turn()})}
function talk(){const wrap=modal('Pick your words.','A stranger by the seep',`<div class="dialogue">“You look like the Heap chewed you up. Don't look so surprised. The Heap does that.”</div><div class="choices"><button class="choice" data-talk="kind"><strong>Offer a ration. Ask about the factions.</strong><small>Build trust. Spend one ration.</small></button><button class="choice" data-talk="sharp"><strong>Ask what they know about the Old Lift.</strong><small>Some paths are more than rumors.</small></button><button class="choice" data-talk="steal"><strong>Distract them. Lift something.</strong><small>Risk a fight for a chance at supplies.</small></button><button class="choice" data-talk="leave"><strong>Say nothing. Keep walking.</strong><small>Not every silence is fear.</small></button></div>`);wrap.querySelectorAll('[data-talk]').forEach(b=>b.onclick=()=>{const t=b.dataset.talk;wrap.remove();if(t==='kind'){if(!inventoryCount('Ration')){notify('You have no ration to offer.');return}s.inventory.Ration--;log('The stranger accepts the ration and shares a name. The Pickers look after their own.');factionTalk()}if(t==='sharp'){log('“Old Lift goes farther than the pipes. Delvers mark the way. Do not follow unless you mean it.”');s.flags.liftHint=true;notify('New lead: Old Lift');turn()}if(t==='steal'){if(Math.random()<.55){const item=['Scrap','Cloth','Rat meat'][rand(0,2)];add(item);log(`While they curse the drip, you palm a ${item.toLowerCase()}.`)}else{s.hp-=8;s.wounds.push({name:'Split lip',penalty:8,effect:'combat'});log('They catch your wrist and put a fist into your mouth. Split lip.');}turn()}if(t==='leave'){log('You leave the stranger to their thoughts.');turn()}})}
function factionTalk(){const f=modal('A place in the Crag.','There is no neutral ground forever',`<p>Your deeds decide whether they trust you. You can only carry one banner. Delvers make a sacred vow: once you join, leaving the search is betrayal.</p><div class="choices">${Object.entries(factions).filter(([name])=>name!==s.faction).map(([name,desc])=>`<button class="choice" data-faction="${name}" ${s.faction==='Delvers'?'disabled':''}><strong>${name}</strong><small>${desc}${name==='Delvers'?' · Permanent vow':''}</small></button>`).join('')}</div>`);f.querySelectorAll('[data-faction]').forEach(b=>b.onclick=()=>{const name=b.dataset.faction;if(s.faction==='Delvers')return;if(name==='Delvers'&&!s.flags.liftHint){notify('You need to learn about the Old Lift first.');return}const old=s.faction;s.faction=name;f.remove();document.querySelector('#faction-name').textContent=name;document.querySelector('#faction-copy').textContent=factions[name];document.querySelectorAll('.quick-stats .stat-chip')[1].querySelector('b').textContent=name==='Unaffiliated'?'—':name.slice(0,3).toUpperCase();log(`${old} → ${name}. ${name==='Delvers'?'The vow is permanent.':'A new banner, and new enemies.'}`);notify(name==='Delvers'?'THE DELVER VOW IS PERMANENT':'Joined '+name);turn()})}
function travel(){const opts=Object.keys(places).filter(p=>p!==s.loc);const w=modal('Where to?','Routes shift when the lights go out',`<p>${s.loc==='Old Lift'&&s.faction==='Delvers'?'You are committed to the upward search.':'You know a few paths. None of them are safe.'}</p><div class="choices">${opts.map(p=>`<button class="choice" data-route="${p}" ${s.loc==='Old Lift'&&s.faction==='Delvers'?'disabled':''}><strong>${p}</strong><small>${places[p].desc} · ${places[p].threat}</small></button>`).join('')}</div>`);w.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{w.remove();go(b.dataset.route)})}

function combat(){const e=s.enemy;if(!e)return;const w=modal('Something wants your blood.','Turn-based encounter',`<div class="combat-top"><span>YOU · ${s.name.toUpperCase()}</span><span id="enemy-name">${e.name.toUpperCase()} · <b id="enemy-hp">${e.hp}</b> / ${e.max}</span></div><div class="combat-bars" id="combat-bars"></div><p id="combat-log" class="mono" style="font-size:10px">Your turn. Choose carefully. Injuries make every action harder.</p><div class="combat-actions"><button class="combat-action" data-fight="attack"><b>Strike</b><small>${inventoryCount('Sharpened shiv')?'Shiv: 19–28 damage':'Pipe: 9–16 damage'}</small></button><button class="combat-action" data-fight="heavy"><b>Heavy swing</b><small>More damage, costs stamina</small></button><button class="combat-action" data-fight="guard"><b>Brace</b><small>Reduce the next hit</small></button><button class="combat-action" data-fight="flee"><b>Get out</b><small>Lose ground, maybe get hurt</small></button></div>`);let guarding=false;function bars(){const box=w.querySelector('#combat-bars');if(box)box.innerHTML=`<div class="meter"><div class="meter-label"><span>YOU · HEALTH</span><span>${Math.round(s.hp)}</span></div><div class="meter-track"><div class="meter-fill health" style="width:${s.hp}%"></div></div></div><div class="meter"><div class="meter-label"><span>${e.name.toUpperCase()}</span><span>${Math.max(0,e.hp)}</span></div><div class="meter-track"><div class="meter-fill hunger" style="width:${Math.max(0,e.hp/e.max*100)}%"></div></div></div>`}bars();w.querySelectorAll('[data-fight]').forEach(b=>b.onclick=()=>{const act=b.dataset.fight;if(act==='flee'){w.remove();s.enemy=null;s.stamina-=8;s.hp-=Math.random()<.38?e.damage:0;log(`You break away from the ${e.name.toLowerCase()} and retreat.`);turn();return}if(act==='guard'){guarding=true;w.querySelector('#combat-log').textContent='You brace and wait for an opening.'}else{const shiv=inventoryCount('Sharpened shiv')>0;let dmg=act==='heavy'?rand(15,23):shiv?rand(19,28):rand(9,16);dmg=Math.max(2,Math.floor(dmg*(1-penalty()/150)));if(act==='heavy'&&s.stamina<12){w.querySelector('#combat-log').textContent='Too tired for a heavy swing.';return}if(act==='heavy')s.stamina-=12;e.hp-=dmg;w.querySelector('#combat-log').textContent=`You hit for ${dmg}. ${e.hp<=0?`The ${e.name.toLowerCase()} stops moving.`:'It comes closer.'}`;if(e.hp<=0){add(e.name==='Rat'?'Rat meat':'Chitin',1);if(e.name==='Rat'&&Math.random()<.45)add('Scrap');log(`You kill the ${e.name.toLowerCase()} and take what you can use.`);w.remove();s.enemy=null;turn();return}}if(!guarding||act!=='guard'){let incoming=Math.max(1,e.damage-Math.floor(penalty()*.08));if(guarding)incoming=Math.ceil(incoming*.35);s.hp-=incoming;guarding=false;w.querySelector('#combat-log').textContent+=` It hits you for ${incoming}.`}bars();renderStats();if(s.hp<=0){w.remove();s.enemy=null;turn();return}})}
function showMenu(){const w=modal('Keep your head down.','Pause · field options',`<p>You can restart your story, or keep moving. The Crag does not pause while you sleep.</p><div class="choices"><button class="choice" id="resume"><strong>Back to the crag</strong><small>Keep surviving.</small></button><button class="choice" id="restart"><strong>Start over</strong><small>Leave this life behind.</small></button><button class="choice" id="how"><strong>Field guide</strong><small>How survival works.</small></button></div>`);w.querySelector('#resume').onclick=()=>w.remove();w.querySelector('#restart').onclick=()=>{w.remove();cancelAnimationFrame(worldAnimation);s={name:'Marlow',origin:'Drifter',tone:0,build:0,scar:0,day:1,turn:0,loc:'The Heap',faction:'Unaffiliated',hp:82,hunger:77,thirst:72,stamina:82,inventory:{'Bent pipe':1,'Ration':1,'Scrap':2,'Cloth':1,'Dirty water':1},wounds:[],shelter:0,flags:{},logs:[],enemy:null,dead:false};creator()};w.querySelector('#how').onclick=()=>{w.remove();const guide=modal('Survive the Crag.','Field guide',`<p>Every action advances time. Hunger and thirst drain over four actions; when either hits zero, health drops. Find water and rations. Rest to regain stamina.</p><p><b>Injuries:</b> wounds drain health each watch, reduce stamina and make combat weaker. A shelter uses 3 scrap and 2 cloth, then restores a little health each day.</p><p><b>Trade:</b> no money exists. Bring the exact goods a Hawker asks for. Weapons are rare and expensive. <b>Combat:</b> turn-based. Strike, heavy swing, brace, or run.</p><p><b>Factions:</b> Pickers scavenge, Hawkers trade, Reapers test the strong, Wardens sell protection. Delvers search for a way up; that vow is permanent.</p>`);guide.querySelector('.close').onclick=()=>guide.remove()}}
function ending(title,copy){const e=document.createElement('div');e.className='ending';e.innerHTML=`<div><div class="eyebrow">BENEATH THE UTOPIA · FIELD RECORD CLOSED</div><h1>${title}</h1><p>${copy}</p><button class="btn primary" id="again">Make another life</button></div>`;document.body.append(e);document.querySelector('#again').onclick=()=>{e.remove();s.dead=false;cancelAnimationFrame(worldAnimation);s={name:'Marlow',origin:'Drifter',tone:0,build:0,scar:0,day:1,turn:0,loc:'The Heap',faction:'Unaffiliated',hp:82,hunger:77,thirst:72,stamina:82,inventory:{'Bent pipe':1,'Ration':1,'Scrap':2,'Cloth':1,'Dirty water':1},wounds:[],shelter:0,flags:{},logs:[],enemy:null,dead:false};creator()}}
creator();
</script></body></html>

