<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#101210"><title>Beneath the Utopia — A Crag Survival Game</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Oswald:wght@400;500;600&display=swap" rel="stylesheet"><style>
:root{--ink:#e7e5d7;--muted:#a19f90;--dim:#737268;--bg:#101210;--panel:#181a17;--panel2:#20221e;--line:#34362f;--lime:#bacd81;--rust:#bb714a;--blue:#85a9a0;--gold:#d8b579;--red:#cf7968;--mono:'DM Mono',monospace;--display:'Oswald',sans-serif;--body:'DM Sans',sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px var(--body);min-height:100vh}button,input{font:inherit}button{color:inherit;cursor:pointer}#app{min-height:100vh}.noise{position:fixed;inset:0;pointer-events:none;opacity:.035;z-index:5;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E")}.mono{font-family:var(--mono)}.eyebrow{font:10px var(--mono);letter-spacing:.18em;text-transform:uppercase;color:var(--lime)}.title{font:500 clamp(42px,8vw,82px)/.87 var(--display);letter-spacing:-.03em;text-transform:uppercase;margin:0}.title span{color:var(--rust)}.btn{border:1px solid var(--line);background:#242620;padding:12px 16px;font:11px var(--mono);letter-spacing:.09em;text-transform:uppercase;transition:.18s}.btn:hover:not(:disabled){background:var(--lime);color:#171912;border-color:var(--lime)}.btn:disabled{opacity:.35;cursor:not-allowed}.btn.primary{background:var(--lime);color:#171912;border-color:var(--lime)}.btn.primary:hover{background:#d2e19e}.btn.danger{border-color:#814d42;color:#e3a08d}.panel{background:var(--panel);border:1px solid var(--line)}
