 function renderGame(){let loc=locations[s.loc];app.innerHTML=`<section id="game"><header class="game-header"><div class="game-title">BENEATH <em>THE UTOPIA</em></div><div class="header-right"><span>DAY ${s.day} · TURN ${s.turn}</span><span>⟡ ${esc(s.faction.toUpperCase())}</span><button class="btn" id="helpBtn">FIELD GUIDE</button></div></header><div class="game-grid"><div class="main-column"><div class="scene"><canvas id="scene-canvas"></canvas><div class="scene-head"><div class="eyebrow">LOWER CITY / ${String(s.day).padStart(2,'0')}</div><h2>${esc(s.loc)}</h2><p>${loc.desc}</p></div><div class="scene-coords">CRAG SECTOR ${loc.x}<br>DEPTH 4,208 M</div><div class="scene-bottom"><div class="threat">⚠${loc.threat}</div><div class="location-buttons">${Object.keys(locations).map(k=>`<button class="${s.loc===k?'active':''}" data-loc="${k}">${k}</button>`).join('')}</div></div></div><div class="action-grid">${[['scavenge','Scavenge','Search the debris for useful things.','⌕'],['hunt','Hunt vermin','Try to catch rats or edible bugs.','⌁'],['water','Find water','Collect or make water safe.','◌'],['shelter','Build shelter','Use materials to make a safer place.','⌂'],['rest','Catch your breath','Recover stamina; hunger advances.','Ⅱ'],['hide','Keep hidden','Avoid attention and steady your nerves.','◒'],['people','Approach survivor','Talk, bargain, or make trouble.','♧'],['inventory','Inventory','Check your belongings and injuries.','▤']].map(([id,title,sub,icon])=>`<button class="action" data-action="${id}"><span class="action-icon">${icon}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div><div class="journal panel"><div class="panel-title">FIELD NOTES <span>LAST ${s.logs.length} EVENTS</span></div><div id="logList">${s.logs.map(x=>`<div class="log-entry ${x.tag}"><span>›</span>${esc(x.text)}</div>`).join('')||'<div class="log-entry">› Your story starts here.</div>'}</div></div></div><aside class="sidebar"><div class="sidepanel panel"><div class="person-head"><div class="avatar">${esc(s.name.slice(0,1).toUpperCase())}</div><div><div class="eyebrow">${esc(s.origin)} / SURVIVOR</div><div class="person-name">${esc(s.name)}</div></div></div><div class="meters">${meter('Health',s.hp,'#cf7968')}${meter('Hunger',s.hunger,'#d8b579')}${meter('Thirst',s.thirst,'#85a9a0')}${meter('Stamina',s.stamina,'#bacd81')}</div><div class="wound-list"><div class="panel-title">INJURIES <span>${s.wounds.length}</span></div>${s.wounds.length?s.wounds.map(w=>`<div class="wound">✕ ${esc(w)}</div>`).join(''):'<div class="quiet">No open wounds. Yet.</div>'}</div></div><div class="sidepanel panel"><div class="panel-title">CARRYING <span>${Object.values(s.inventory).reduce((a,b)=>a+b,0)} ITEMS</span></div><div class="inventory-list">${Object.entries(s.inventory).filter(x=>x[1]>0).map(([k,n])=>`<div><span>${esc(k)}</span><b>×${n}</b></div>`).join('')||'<div class="quiet">Nothing worth keeping.</div>'}</div></div><div class="sidepanel panel faction-panel"><div class="panel-title">THE SIX GROUPS</div>${Object.entries(factions).map(([k,v])=>`<div class="faction-row ${s.faction===k?'current':''}"><b>${k}</b><small>${v}</small></div>`).join('')}</div><button id="restart" class="btn">Abandon this run</button></aside></div></section>`;
 app.querySelectorAll('[data-loc]').forEach(b=>b.onclick=()=>{s.loc=b.dataset.loc;advance(1);renderGame();initThree('#scene-canvas')});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelector('#helpBtn').onclick=()=>openGuide();document.querySelector('#restart').onclick=()=>{if(confirm('Leave this run and create a new survivor?')){s={...s,name:'Marlow',origin:'Drifter',tone:0,build:0,day:1,turn:0,loc:'The Heap',faction:'Unaffiliated',hp:82,hunger:77,thirst:72,stamina:82,inventory:{'Bent pipe':1,Ration:1,Scrap:2,Cloth:1,'Dirty water':1},wounds:[],shelter:0,flags:{},logs:[],enemy:null,dead:false};renderCreator()}};}
+function advance(n=1){for(let i=0;i<n;i++){s.turn++;s.hunger=clamp(s.hunger-4);s.thirst=clamp(s.thirst-6);s.stamina=clamp(s.stamina-3);if(s.turn%7===0)s.day++;if(s.hunger===0)s.hp-=3;if(s.thirst===0)s.hp-=6;if(s.hp<=0){s.hp=0;s.dead=true;ending('The Crag keeps another name','Hunger and thirst finally took what the city started. The tunnels do not remember you.')}}}
+function refresh(){renderGame();initThree('#scene-canvas')}
+function toastLog(text,tag=''){log(text,tag);notify(text);if(!s.dead)refresh()}
