+function action(which){if(s.dead)return;const cost={scavenge:8,hunt:12,water:8,shelter:7,rest:0,hide:5,people:6,inventory:0}[which]||0;if(s.stamina<cost){notify('Too exhausted. Rest first.');return}if(which==='people'){advance(1);openPeople();return}if(which==='inventory'){openInventory();return}advance(1);s.stamina=clamp(s.stamina-cost+ (which==='rest'?25:0));if(s.dead)return;
+if(which==='scavenge'){const rolls=[['Scrap',2],['Cloth',1],['Wire spool',1],['Ration',1],['Bandage',1],['Bent pipe',1]];let [item,n]=rolls[rand(0,rolls.length-1)];if(s.loc==='The Heap'&&Math.random()<.48){add(item,n);toastLog(`You pulled ${n>1?n+' ':''}${item} from the Heap.`,'good')}else if(Math.random()<.62){add(item,n);toastLog(`You found ${item}. Something else was looking.`,'good')}else startCombat('Heap lurker')}else if(which==='hunt'){if(Math.random()<.62){let item=Math.random()<.6?'Rat meat':'Bug meat';add(item,1);s.hunger=clamp(s.hunger+12);toastLog(`You caught ${item.toLowerCase()}. Raw, but edible.`,'good')}else startCombat('Tunnel rat')}else if(which==='water'){if(s.loc==='Dripline'&&Math.random()<.75){add('Dirty water',2);toastLog('You filled two bottles from the seep. Boil it before drinking.','good')}else if(inventoryCount('Dirty water')&&inventoryCount('Filter')){spend('Dirty water');spend('Filter');add('Clean water');toastLog('You filtered a bottle of clean water.','good')}else if(Math.random()<.4){add('Dirty water');toastLog('A small catch of dirty water. Better than nothing.','good')}else toastLog('Only rust-colored puddles. You need a filter or a safer source.')}else if(which==='shelter'){if(s.shelter){s.stamina=clamp(s.stamina+8);toastLog('You reinforce your shelter. It will soften the next blow.','good')}else if(spend('Scrap',2)&&spend('Cloth')){s.shelter=1;toastLog('You made a low shelter from scrap and cloth. It is not home, but it is yours.','good')}else toastLog('You need 2 Scrap and 1 Cloth to build a shelter.')}else if(which==='rest'){s.stamina=clamp(s.stamina+27);if(s.shelter){s.hp=clamp(s.hp+5);toastLog('You rest beneath your shelter. The roof holds.','good')}else if(Math.random()<.28){s.hp=clamp(s.hp-8);toastLog('You wake to a boot in your ribs. Never sleep unguarded.','bad')}else toastLog('You rest with one eye open. Stamina recovered.')}else if(which==='hide'){s.stamina=clamp(s.stamina+4);if(Math.random()<.6){toastLog('You stay out of sight. Footsteps pass without stopping.','good')}else {s.hp=clamp(s.hp-4);toastLog('A Reaper spots you in the shadows. You scramble away, bruised.','bad')}}}
+function openPeople(){const characters=[{name:'Iona, Picker',group:'Pickers',line:'The Heap is alive. Bring me wire and cloth; I can make something useful.'},{name:'Vell, Hawker',group:'Hawkers',line:'No tokens here. Trade a ration for a bandage, or two scrap for a clean bottle. Weapons cost dearly.'},{name:'Marek, Reaper',group:'Reapers',line:'Strong keep what they can hold. A pipe buys respect. Or a fight.'},{name:'Sister Vale, Delver',group:'Delvers',line:'We search for the old ascent. Our vow is absolute: no Delver leaves.'},{name:'Orr, Warden',group:'Wardens',line:'Pay in supplies, not promises. I can watch your back—for a ration.'},{name:'Nim, unaffiliated',group:'Unaffiliated',line:'Nobody owns me. Share a little water and I might share a secret.'}];let c=characters.find(x=>x.group===s.faction)||characters[rand(0,characters.length-1)];modal=`<div class="eyebrow">A PERSON IN THE DARK</div><h2>${c.name}</h2><p class="dialogue">“${c.line}”</p><div class="choices"><button class="choice" data-choice="trade"><strong>Ask what they need</strong><small>Trade goods for goods. There is no currency.</small></button><button class="choice" data-choice="join"><strong>Ask about ${c.group}</strong><small>Learn their terms and decide where you stand.</small></button><button class="choice" data-choice="fight"><strong>Make a threat</strong><small>Could become a turn-based fight.</small></button><button class="choice" data-choice="leave"><strong>Leave quietly</strong><small>Keep your hands to yourself.</small></button></div>`;showModal();document.querySelector('[data-choice="trade"]').onclick=()=>openTrade(c);document.querySelector('[data-choice="join"]').onclick=()=>joinFaction(c);document.querySelector('[data-choice="fight"]').onclick=()=>{closeModal();startCombat(c.name)};document.querySelector('[data-choice="leave"]').onclick=closeModal}
+function joinFaction(c){if(c.group==='Delvers'){modal=`<div class="eyebrow">A PERMANENT VOW</div><h2>The Delver oath</h2><p>“We do not leave until all can leave.” Joining binds you to the search. Even if you find the ascent, you will not take it alone—and the vow cannot be broken.</p><div class="choices"><button class="choice" id="vow"><strong>Swear the vow</strong><small>Become a Delver. This cannot be undone.</small></button><button class="choice" id="noVow"><strong>Not yet</strong><small>Keep your current allegiance.</small></button></div>`;showModal();document.querySelector('#vow').onclick=()=>{s.faction='Delvers';s.flags.delverVow=true;closeModal();toastLog('You swore the Delver vow. There is no leaving it.','good')};document.querySelector('#noVow').onclick=()=>{closeModal();openPeople()};return}if(c.group==='Reapers'&&!inventoryCount('Bent pipe')&&!inventoryCount('Knife')){modal=`<div class="eyebrow">THE REAPERS</div><h2>Prove you can keep it</h2><p>They do not accept a promise. Bring a weapon, then return to talk. Their protection is another kind of danger.</p><button class="btn" id="back">Back</button>`;showModal();document.querySelector('#back').onclick=closeModal;return}s.faction=c.group;closeModal();toastLog(`You are now recognized among the ${c.group}. Allegiance brings company, not safety.`,'good')}

