Allegiance brings company, not safety.`,'good')}
function openTrade(c){let html=`<div class="eyebrow">BARTER / GOODS ONLY</div><h2>${c.group} exchange</h2>`;let offers=[];if(c.group==='Hawkers')offers=[['Ration','Bandage','Weapons cost at least three useful goods.'],['Scrap','Clean water','Two scrap for one clean bottle.'],['Cloth','Filter','Trade cloth for a filter.']];else if(c.group==='Pickers')offers=[['Wire spool','Knife','A carefully made blade.'],['Cloth','Bandage','One cloth for one bandage.']];else if(c.group==='Wardens')offers=[['Ration','Protection','A Warden watches you for a day.']];else offers=[['Rat meat','Scrap','Food for building material.'],['Dirty water','Cloth','A simple exchange.']];html+=`<div class="choices">${offers.map((o,i)=>`<button class="choice" data-offer="${i}"><strong>Give ${o[0]} → receive ${o[1]}</strong><small>${o[2]} · You have ${inventoryCount(o[0])} ${o[0]}.</small></button>`).join('')}<button class="choice" id="tradeBack"><strong>Back</strong><small>Return to the conversation.</small></button></div>`;modal=html;showModal();document.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>{let [give,get]=offers[+b.dataset.offer];if(!spend(give)){notify(`You do not have ${give}.`);return}if(get==='Protection'){s.flags.wardenUntil=s.day+1;closeModal();toastLog('The Warden takes your ration and promises to watch the next stretch.','good');return}if(get==='Clean water'){add('Clean water');s.inventory['Clean water']=(s.inventory['Clean water']||0)-1;add('Dirty water');spend('Dirty water');add('Clean water');}else add(get);closeModal();toastLog(`Bartered ${give} for ${get}. No tokens changed hands.`,'good')});document.querySelector('#tradeBack').onclick=()=>{closeModal();openPeople()}}
function openInventory(){modal=`<div class="eyebrow">WHAT YOU CARRY</div><h2>Inventory & injuries</h2><p>${Object.entries(s.inventory).filter(x=>x[1]>0).map(([k,n])=>`${esc(k)} ×${n}`).join(' · ')||'Nothing'}.</p><p>${s.wounds.length?'Wounds: '+s.wounds.map(esc).join(', '):'No injuries.'}</p><div class="choices"><button class="choice" id="eat"><strong>Eat a ration or meat</strong><small>Recover hunger. Food can be raw; raw food is risky.</small></button><button class="choice" id="drink"><strong>Drink water</strong><small>Clean water is safest. Dirty water may make you sick.</small></button><button class="choice" id="bandage"><strong>Use a bandage</strong><small>Heal an open wound and restore health.</small></button><button class="choice" id="closeInv"><strong>Close</strong></button></div>`;showModal();document.querySelector('#eat').onclick=()=>{let food=['Ration','Rat meat','Bug meat'].find(x=>inventoryCount(x));if(!food){notify('No food to eat.');return}spend(food);s.hunger=clamp(s.hunger+(food==='Ration'?35:22));if(food!=='Ration'&&Math.random()<.2){s.hp=clamp(s.hp-7);s.wounds.push('stomach sickness')}closeModal();toastLog(`You ate ${food.toLowerCase()}.`,'good')};document.querySelector('#drink').onclick=()=>{let water=['Clean water','Dirty water'].find(x=>inventoryCount(x));if(!water){notify('No water to drink.');return}spend(water);s.thirst=clamp(s.thirst+(water==='Clean water'?38:24));if(water==='Dirty water'&&Math.random()<.3){s.hp=clamp(s.hp-6);s.wounds.push('fever')}closeModal();toastLog(`You drank ${water.toLowerCase()}.`,'good')};document.querySelector('#bandage').onclick=()=>{if(!spend('Bandage')){notify('You have no bandage.');return}if(s.wounds.length)s.wounds.shift();s.hp=clamp(s.hp+22);closeModal();toastLog('You bound your injury and caught your breath.','good')};document.querySelector('#closeInv').onclick=closeModal}
function startCombat(name){s.enemy={name,hp:44,turn:0};modal=`<div class="eyebrow">HOSTILE ENCOUNTER</div><h2>${esc(name)}</h2><div class="combat-top"><span>YOU · ${s.name}</span><span>OPPONENT · ${esc(name)}</span></div><div class="combat-bars">${meter('Your health',s.hp,'#cf7968')}${meter('Threat',s.enemy.hp,'#bb714a')}</div><p class="dialogue">The tunnel narrows. There is still time to choose what kind of person you are.</p><div class="combat-actions"><button class="combat-action" data-fight="strike"><b>Strike</b><small>Use a weapon if you have one.</small></button><button class="combat-action" data-fight="talk"><b>Talk</b><small>Offer a way out.</small></button><button class="combat-action" data-fight="flee"><b>Flee</b><small>Leave your pride behind.</small></button><button class="combat-action" data-fight="guard"><b>Guard</b><small>Reduce the next blow.</small></button></div>`;showModal();document.querySelectorAll('[data-fight]').forEach(b=>b.onclick=()=>combatTurn(b.dataset.fight))}
function combatTurn(choice){if(!s.enemy)return;if(choice==='talk'&&Math.random()<.48){let n=s.enemy.name; s.enemy=null;closeModal();toastLog(`${n} lowers their guard. You both leave breathing.`,'good');return}if(choice==='flee'&&Math.random()<.64){s.enemy=null;closeModal();toastLog('You escape into the dark, bruised but alive.','good');return}let damage=choice==='strike'?(inventoryCount('Bent pipe')||inventoryCount('Knife')?22:9):0;if(choice==='strike')s.enemy.hp-=damage;let guarded=choice==='guard';if(s.enemy.hp<=0){let n=s.enemy.name;s.enemy=null;s.stamina=clamp(s.stamina-8);closeModal();toastLog(`You survived the fight with ${n}. Your hands are still shaking.`,'good');return}let hit=guarded?rand(2,7):rand(7,17);if(s.shelter){hit=Math.max(1,hit-5);s.shelter=0}if(s.flags.wardenUntil>=s.day)hit=Math.max(0,hit-4);s.hp=clamp(s.hp-hit);s.stamina=clamp(s.stamina-8);s.enemy.turn++;if(s.hp<=0){s.enemy=null;closeModal();ending('The Crag keeps another name','Your body gives out in the dark. Nobody hears the last breath.');return}if(Math.random()<.18){let w=['split lip','bruised ribs','cut forearm'][rand(0,2)];if(!s.wounds.includes(w))s.wounds.push(w)}let n=s.enemy.name;modal=`<div class="eyebrow">THE FIGHT CONTINUES</div><h2>${esc(n)}</h2><div class="combat-top"><span>YOU · ${s.hp} HEALTH</span><span>THREAT · ${Math.max(0,s.enemy.hp)} HEALTH</span></div><p class="dialogue">${choice==='talk'?'Your words are swallowed by the tunnel.':choice==='flee'?'They cut off the escape.':choice==='guard'?'You weather the blow behind your guard.':'You strike; they answer in kind.'} You take ${hit} damage.</p><div class="combat-actions"><button class="combat-action" data-fight="strike"><b>Strike</b><small>Attack again</small></button><button class="combat-action" data-fight="talk"><b>Talk</b><small>Try to end this</small></button><button class="combat-action" data-fight="flee"><b>Flee</b><small>Look for an opening</small></button><button class="combat-action" data-fight="guard"><b>Guard</b><small>Brace for impact</small></button></div>`;showModal();document.querySelectorAll('[data-fight]').forEach(b=>b.onclick=()=>combatTurn(b.dataset.fight))}

