 function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
 function start(){s.name=(document.querySelector('#nameInput')?.value||'Marlow').trim().slice(0,18)||'Marlow';renderGame();initThree('#scene-canvas');log(`${s.name} wakes beneath the city. The air tastes of rust.`);notify('No way back up. Find water.');}
 function renderCreator(){app.innerHTML=`<section id="creator"><div class="topline"><div class="brand">CRAG / <b>FIELD NOTES</b></div><div class="eyebrow">A survival story · cycle 01</div></div><div class="creator-grid"><div class="create-copy"><div class="eyebrow">You have been here before. Not like this.</div><h1 class="title">Beneath<br>the <span>Utopia</span></h1><p class="intro">Upstairs, the city calls itself perfect. Down here, everything useful has already belonged to someone. Make a life from what it left behind.</p><div class="section-label">01 / Name your survivor</div><input id="nameInput" class="field" maxlength="18" value="Marlow" aria-label="Survivor name"><div class="section-label">02 / Choose an origin</div><div class="origin-grid">${Object.entries(origins).map(([k,v])=>`<button class="origin ${k===s.origin?'active':''}" data-origin="${k}"><strong>${k}</strong><small>${v}</small></button>`).join('')}</div><div class="section-label">03 / Shape & history</div><div class="appearance"><div class="slider-row"><label>Build <span id="buildVal">Balanced</span></label><input id="build" type="range" min="0" max="2" value="${s.build}"></div><div class="slider-row"><label>Complexion <span id="toneVal">${['Pale','Olive','Deep'][s.tone]}</span></label><input id="tone" type="range" min="0" max="2" value="${s.tone}"></div></div><div class="section-label">A vow is not a plan</div><p class="creator-note">The Delvers believe there is a way out. Their vow forbids leaving. You may join them, but the promise is permanent.</p><div class="create-foot"><button id="begin" class="btn primary">Enter the Crag →</button><span class="creator-note">No currency. No easy choices.</span></div></div><div class="model-wrap"><canvas id="creator-canvas"></canvas><div class="model-caption"><span>SUBJECT / 001</span><span id="modelOrigin">DRIFTER</span></div><div class="model-mark">THE CITY DOES NOT<br>LOOK DOWN.</div></div></div></section>`;
 app.querySelectorAll('[data-origin]').forEach(b=>b.onclick=()=>{s.origin=b.dataset.origin;app.querySelectorAll('[data-origin]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#modelOrigin').textContent=s.origin.toUpperCase()});for(const id of ['build','tone'])document.querySelector('#'+id).oninput=e=>{s[id]=+e.target.value;const labels=id==='build'?['Lean','Balanced','Sturdy']:['Pale','Olive','Deep'];document.querySelector('#'+id+'Val').textContent=labels[s[id]];updatePerson()};document.querySelector('#begin').onclick=start;initThree('#creator-canvas',true)}
